// Sem conta YouTube ligada no Composio: não faz nada (fica à espera da autorização).
// Conta ligada a outro canal (ex. o pessoal): pára com erro, nunca responde com o canal errado.
const r = $json;
const erro = JSON.stringify(r.error || '');
if (erro.includes('ConnectedAccountNotFound')) return [];
if (!r.successful) throw new Error('Composio (canal): ' + erro.slice(0, 300));
const id = (((r.data || {}).items || [])[0] || {}).id;
if (id !== 'O_ID_DO_TEU_CANAL') throw new Error('A conta YouTube ligada é do canal ' + id + ', não do o teu canal. Não respondo.');
return [{ json: { ok: true } }];

// MON-292: regra das respostas automáticas aos comentários do YouTube (o teu canal).
// O YouTube não tem DM: a resposta é pública e aponta para a descrição.
// Este código é o corpo do nó Code "Escolher resposta"; aqui exporta-se para o teste.
// Entrada: resposta de commentThreads.list (part=snippet,replies, allThreadsRelatedToChannelId).

// Textos do Growth (MON-293). A variação sai do id do comentário: estável entre execuções.
const TEXTO = {
  generico: ['O link está na descrição do vídeo 👆', 'Está tudo explicado na descrição do vídeo 👆',
    'Achas o link na descrição deste vídeo 👆'],
  produto: ['O link para NOME está na descrição do vídeo 👆', 'NOME está na descrição deste vídeo, só precisas de abrir 👆',
    'Encontras NOME na descrição do vídeo 👆'],
};
const variacao = (lista, id) => lista[[...String(id)].reduce((h, c) => h + c.charCodeAt(0), 0) % lista.length];
const frase = (modelo, nome) => {
  const t = modelo.replace('NOME', nome);
  return t.charAt(0).toUpperCase() + t.slice(1);                // "o PIGGY..." no início fica "O PIGGY..."
};
const PRODUTOS = [
  { palavra: 'playbook', nome: 'o Playbook de Proteção', slug: 'playbook-servidor' },
  { palavra: 'piggy', nome: 'o PIGGY + LifeOS', slug: 'piggy-lifeos' },
  { palavra: 'pihole', nome: 'o Pi-hole anti-apostas', slug: 'pihole-apostas' },
  { palavra: 'ajuda', nome: 'a Assistência KCU', slug: 'assistencia' },
  // MON-298 (aprovado 24/10): produto novo, está na mesma página de funil dos outros.
  { palavra: 'checklist', nome: 'a Checklist de Segurança do Servidor', slug: 'playbook-servidor' },
];
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/-/g, '');
const temPalavra = (t, p) => new RegExp('(^|[^a-z0-9])' + p + '([^a-z0-9]|$)').test(t);

// threads: items da API; canal: id do canal o teu canal; respondidos: { commentId: isoDate } (static data do workflow)
function escolher(threads, canal, respondidos) {
  const out = [];
  for (const t of threads || []) {
    const top = (t.snippet && t.snippet.topLevelComment) || {};
    const s = top.snippet || {};
    const autor = (s.authorChannelId && s.authorChannelId.value) || '';
    if (!top.id || respondidos[top.id]) continue;                // nunca duas vezes
    if (autor === canal) continue;                               // nunca ao próprio canal
    if (t.snippet && t.snippet.canReply === false) continue;
    const jaRespondeu = ((t.replies && t.replies.comments) || [])
      .some(r => ((r.snippet.authorChannelId || {}).value || '') === canal);
    if (jaRespondeu) { respondidos[top.id] = 'ja-tinha'; continue; } // respondido à mão ou antes da tabela
    const texto = norm(s.textOriginal || s.textDisplay);
    if (!texto.trim()) continue;
    const p = PRODUTOS.find(p => temPalavra(texto, p.palavra));
    out.push({ parentId: top.id, videoId: s.videoId || (t.snippet && t.snippet.videoId) || '',
      palavra: p ? p.palavra : '', texto: p ? frase(variacao(TEXTO.produto, top.id), p.nome) : variacao(TEXTO.generico, top.id) });
  }
  return out;
}

// Ponto 2: a descrição tem um link /go/<slug>/ do funil?
const RE_GO = /https?:\/\/o-teu-site\.exemplo\/go\/([a-z0-9-]*)\/?/i;
function linkDescricao(descricao) {
  const m = String(descricao || '').match(RE_GO);
  return m ? (m[1] || '(índice)') : null;
}

// --- n8n ---
const r = $json;
if (!r.successful) throw new Error('Composio (comentários): ' + JSON.stringify(r.error || '').slice(0, 300));
const st = $getWorkflowStaticData('global');
st.respondidos = st.respondidos || {};
const res = escolher((r.data || {}).items || [], 'O_ID_DO_TEU_CANAL', st.respondidos);
return res.map(x => ({ json: x }));

// Só marca como respondido o que o YouTube aceitou; o resto tenta outra vez daqui a 10 min.
const st = $getWorkflowStaticData('global');
st.respondidos = st.respondidos || {};
const pedidos = $('Escolher resposta').all();
const falhas = [];
const out = $input.all().map((it, i) => {
  const p = pedidos[i].json;
  if (it.json.successful) st.respondidos[p.parentId] = new Date().toISOString();
  else falhas.push(p.parentId + ': ' + JSON.stringify(it.json.error || '').slice(0, 200));
  return { json: { parentId: p.parentId, videoId: p.videoId, texto: p.texto, ok: !!it.json.successful } };
});
if (falhas.length) throw new Error('Respostas falhadas: ' + falhas.join(' | '));
return out;
